import pandas as pd
import json
import math

# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
total_games = len(df)

# ── Helper: safe percent ───────────────────────────────────────────────────
def pct(n, total):
    return round(100 * n / total, 2) if total else 0

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 1 — Dataset Overview & Game Distribution
# ═══════════════════════════════════════════════════════════════════════════
rated_counts = df['rated'].value_counts()
rated_true = int(rated_counts.get(True, 0))
rated_false = int(rated_counts.get(False, 0))

victory_counts = df['victory_status'].value_counts()
victory_data = {k: int(v) for k, v in victory_counts.items()}

winner_counts = df['winner'].value_counts()
winner_data = {k: int(v) for k, v in winner_counts.items()}

decisive_games = df[df['winner'] != 'draw']
decisive_total = len(decisive_games)

# Average turns overall and by victory status
avg_turns_overall = round(df['turns'].mean(), 1)
avg_turns_by_status = df.groupby('victory_status')['turns'].mean().round(1).to_dict()

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 2 — White vs. Black: First-Move Advantage
# ═══════════════════════════════════════════════════════════════════════════
white_wins = int(winner_data.get('white', 0))
black_wins = int(winner_data.get('black', 0))
draws = int(winner_data.get('draw', 0))

white_wr_decisive = pct(white_wins, decisive_total)
black_wr_decisive = pct(black_wins, decisive_total)

# By rating bracket
def rating_bracket(r):
    if r < 1000: return '<1000'
    elif r < 1200: return '1000-1199'
    elif r < 1400: return '1200-1399'
    elif r < 1600: return '1400-1599'
    elif r < 1800: return '1600-1799'
    elif r < 2000: return '1800-1999'
    else: return '2000+'

df['avg_rating'] = (df['white_rating'] + df['black_rating']) / 2
df['rating_bracket'] = df['avg_rating'].apply(rating_bracket)

bracket_order = ['<1000', '1000-1199', '1200-1399', '1400-1599', '1600-1799', '1800-1999', '2000+']

color_by_bracket = []
for b in bracket_order:
    sub = df[df['rating_bracket'] == b]
    dec = sub[sub['winner'] != 'draw']
    n = len(dec)
    if n == 0:
        continue
    w = len(dec[dec['winner'] == 'white'])
    bl = len(dec[dec['winner'] == 'black'])
    color_by_bracket.append({
        'bracket': b,
        'total': n,
        'white_pct': pct(w, n),
        'black_pct': pct(bl, n),
    })

# By time control (top N)
top_increments = df['increment_code'].value_counts().head(10).index.tolist()
color_by_tc = []
for tc in top_increments:
    sub = df[df['increment_code'] == tc]
    dec = sub[sub['winner'] != 'draw']
    n = len(dec)
    if n == 0:
        continue
    w = len(dec[dec['winner'] == 'white'])
    bl = len(dec[dec['winner'] == 'black'])
    color_by_tc.append({
        'tc': tc,
        'total': n,
        'white_pct': pct(w, n),
        'black_pct': pct(bl, n),
    })

# By victory status
color_by_vs = []
for vs in ['mate', 'resign', 'outoftime']:
    sub = df[df['victory_status'] == vs]
    n = len(sub)
    if n == 0:
        continue
    w = len(sub[sub['winner'] == 'white'])
    bl = len(sub[sub['winner'] == 'black'])
    color_by_vs.append({
        'status': vs,
        'total': n,
        'white_pct': pct(w, n),
        'black_pct': pct(bl, n),
    })

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 3 — Rating Dynamics
# ═══════════════════════════════════════════════════════════════════════════
rating_stats = {
    'white_mean': round(df['white_rating'].mean(), 1),
    'white_median': round(df['white_rating'].median(), 1),
    'white_std': round(df['white_rating'].std(), 1),
    'black_mean': round(df['black_rating'].mean(), 1),
    'black_median': round(df['black_rating'].median(), 1),
    'black_std': round(df['black_rating'].std(), 1),
}

# Rating distribution histogram bins
rating_bins = list(range(600, 2801, 100))
white_hist = pd.cut(df['white_rating'], bins=rating_bins).value_counts().sort_index()
black_hist = pd.cut(df['black_rating'], bins=rating_bins).value_counts().sort_index()

rating_dist_data = []
for interval in white_hist.index:
    mid = int((interval.left + interval.right) / 2)
    rating_dist_data.append({
        'rating': mid,
        'white': int(white_hist.get(interval, 0)),
        'black': int(black_hist.get(interval, 0)),
    })

# Rating differential vs win probability
df['rating_diff'] = df['white_rating'] - df['black_rating']
df_decisive = df[df['winner'] != 'draw'].copy()
df_decisive['higher_rated_won'] = (
    ((df_decisive['rating_diff'] > 0) & (df_decisive['winner'] == 'white')) |
    ((df_decisive['rating_diff'] < 0) & (df_decisive['winner'] == 'black'))
)

# Bin rating differentials
diff_bins = list(range(-800, 801, 50))
df_decisive['diff_bin'] = pd.cut(df_decisive['rating_diff'], bins=diff_bins)

diff_analysis = df_decisive.groupby('diff_bin', observed=True).agg(
    total=('winner', 'count'),
    higher_won=('higher_rated_won', 'sum')
).reset_index()
diff_analysis['win_prob'] = (diff_analysis['higher_won'] / diff_analysis['total'] * 100).round(1)
diff_analysis['mid'] = diff_analysis['diff_bin'].apply(lambda x: int((x.left + x.right) / 2))

diff_data = []
for _, row in diff_analysis.iterrows():
    if row['total'] >= 10:
        diff_data.append({
            'diff': row['mid'],
            'win_prob': float(row['win_prob']),
            'count': int(row['total']),
        })

# Absolute rating diff vs higher-rated win prob
df_decisive['abs_diff'] = df_decisive['rating_diff'].abs()
abs_bins = [0, 25, 50, 75, 100, 150, 200, 300, 400, 500, 600, 800, 1000, 1500, 2000]
df_decisive['abs_diff_bin'] = pd.cut(df_decisive['abs_diff'], bins=abs_bins)

abs_diff_analysis = df_decisive.groupby('abs_diff_bin', observed=True).agg(
    total=('winner', 'count'),
    higher_won=('higher_rated_won', 'sum')
).reset_index()
abs_diff_analysis['win_prob'] = (abs_diff_analysis['higher_won'] / abs_diff_analysis['total'] * 100).round(1)
abs_diff_analysis['label'] = abs_diff_analysis['abs_diff_bin'].apply(lambda x: f"{int(x.left)}-{int(x.right)}")

abs_diff_data = []
for _, row in abs_diff_analysis.iterrows():
    if row['total'] >= 10:
        abs_diff_data.append({
            'label': row['label'],
            'win_prob': float(row['win_prob']),
            'count': int(row['total']),
        })

# Correlation
corr_val = round(df_decisive['rating_diff'].corr(df_decisive['higher_rated_won'].astype(int)), 3)

# Avg turns by rating tier
tier_order = ['<1000', '1000-1199', '1200-1399', '1400-1599', '1600-1799', '1800-1999', '2000+']
df['white_tier'] = df['white_rating'].apply(rating_bracket)
df['black_tier'] = df['black_rating'].apply(rating_bracket)

avg_turns_tier = []
for t in tier_order:
    sub = df[(df['white_tier'] == t) | (df['black_tier'] == t)]
    if len(sub) > 0:
        avg_turns_tier.append({
            'tier': t,
            'avg_turns': round(sub['turns'].mean(), 1),
            'games': len(sub),
        })

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 4 — Opening Analysis
# ═══════════════════════════════════════════════════════════════════════════
# Top openings by ECO + name
opening_counts = df.groupby(['opening_eco', 'opening_name']).size().reset_index(name='count')
opening_counts = opening_counts.sort_values('count', ascending=False).head(15)

top_openings = []
for _, row in opening_counts.iterrows():
    eco = row['opening_eco']
    name = row['opening_name']
    sub = df[(df['opening_eco'] == eco) & (df['opening_name'] == name)]
    dec = sub[sub['winner'] != 'draw']
    n_dec = len(dec)
    w = len(dec[dec['winner'] == 'white']) if n_dec else 0
    bl = len(dec[dec['winner'] == 'black']) if n_dec else 0
    dr = len(sub[sub['winner'] == 'draw'])
    top_openings.append({
        'eco': eco,
        'name': name,
        'total': int(row['count']),
        'white_pct': pct(w, n_dec) if n_dec else 0,
        'black_pct': pct(bl, n_dec) if n_dec else 0,
        'draw_pct': pct(dr, len(sub)),
        'avg_ply': round(sub['opening_ply'].mean(), 1),
        'avg_turns': round(sub['turns'].mean(), 1),
    })

# Openings where black outperforms white (top 30 by frequency)
all_openings = df.groupby(['opening_eco', 'opening_name']).agg(
    total=('id', 'count'),
    white_wins=('winner', lambda x: (x == 'white').sum()),
    black_wins=('winner', lambda x: (x == 'black').sum()),
    draws=('winner', lambda x: (x == 'draw').sum()),
).reset_index()
all_openings = all_openings[all_openings['total'] >= 50].sort_values('total', ascending=False)

black_favored = []
for _, row in all_openings.head(50).iterrows():
    dec = row['total'] - row['draws']
    if dec >= 30:
        bp = pct(row['black_wins'], dec)
        wp = pct(row['white_wins'], dec)
        if bp > wp:
            black_favored.append({
                'eco': row['opening_eco'],
                'name': row['opening_name'],
                'total': int(row['total']),
                'white_pct': wp,
                'black_pct': bp,
            })

black_favored = sorted(black_favored, key=lambda x: x['black_pct'] - x['white_pct'], reverse=True)[:5]

# Opening ply vs outcome
ply_bins = [0, 2, 4, 6, 8, 10, 15, 20, 30, 50]
df['ply_bin'] = pd.cut(df['opening_ply'], bins=ply_bins)
ply_analysis = df.groupby('ply_bin', observed=True).agg(
    total=('id', 'count'),
    white_wins=('winner', lambda x: (x == 'white').sum()),
    black_wins=('winner', lambda x: (x == 'black').sum()),
    draws=('winner', lambda x: (x == 'draw').sum()),
    avg_turns=('turns', 'mean'),
).reset_index()
ply_analysis['label'] = ply_analysis['ply_bin'].apply(lambda x: f"{int(x.left)}-{int(x.right)}")

ply_data = []
for _, row in ply_analysis.iterrows():
    dec = row['total'] - row['draws']
    ply_data.append({
        'label': row['label'],
        'total': int(row['total']),
        'white_pct': pct(row['white_wins'], dec) if dec else 0,
        'black_pct': pct(row['black_wins'], dec) if dec else 0,
        'draw_pct': pct(row['draws'], row['total']),
        'avg_turns': round(row['avg_turns'], 1),
    })

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 5 — Time Control Patterns
# ═══════════════════════════════════════════════════════════════════════════
tc_counts = df['increment_code'].value_counts().head(12)
tc_data = []
for tc, count in tc_counts.items():
    sub = df[df['increment_code'] == tc]
    vs_dist = sub['victory_status'].value_counts(normalize=True).mul(100).round(1).to_dict()
    tc_data.append({
        'tc': tc,
        'total': int(count),
        'avg_turns': round(sub['turns'].mean(), 1),
        'mate_pct': float(vs_dist.get('mate', 0)),
        'resign_pct': float(vs_dist.get('resign', 0)),
        'outoftime_pct': float(vs_dist.get('outoftime', 0)),
        'draw_pct': float(vs_dist.get('draw', 0)),
    })

# Classify time controls
def classify_tc(tc):
    try:
        base = int(tc.split('+')[0])
        if base <= 3: return 'Bullet'
        elif base <= 10: return 'Blitz'
        elif base <= 30: return 'Rapid'
        else: return 'Classical'
    except:
        return 'Other'

df['tc_category'] = df['increment_code'].apply(classify_tc)

tc_cat_order = ['Bullet', 'Blitz', 'Rapid', 'Classical']
tc_cat_data = []
for cat in tc_cat_order:
    sub = df[df['tc_category'] == cat]
    if len(sub) == 0:
        continue
    dec = sub[sub['winner'] != 'draw']
    n_dec = len(dec)
    vs_dist = sub['victory_status'].value_counts(normalize=True).mul(100).round(1).to_dict()
    tc_cat_data.append({
        'category': cat,
        'total': len(sub),
        'avg_turns': round(sub['turns'].mean(), 1),
        'white_pct': pct(len(dec[dec['winner'] == 'white']), n_dec) if n_dec else 0,
        'black_pct': pct(len(dec[dec['winner'] == 'black']), n_dec) if n_dec else 0,
        'mate_pct': float(vs_dist.get('mate', 0)),
        'resign_pct': float(vs_dist.get('resign', 0)),
        'outoftime_pct': float(vs_dist.get('outoftime', 0)),
        'draw_pct': float(vs_dist.get('draw', 0)),
    })

# ═══════════════════════════════════════════════════════════════════════════
#  KPI Calculations
# ═══════════════════════════════════════════════════════════════════════════
checkmate_rate = pct(victory_data.get('mate', 0), total_games)
resign_rate = pct(victory_data.get('resign', 0), total_games)
outoftime_rate = pct(victory_data.get('outoftime', 0), total_games)

# ═══════════════════════════════════════════════════════════════════════════
#  BUILD HTML
# ═══════════════════════════════════════════════════════════════════════════

# Serialize data for JS charts
js_data = {
    'winner_data': winner_data,
    'victory_data': victory_data,
    'color_by_bracket': color_by_bracket,
    'color_by_tc': color_by_tc,
    'color_by_vs': color_by_vs,
    'rating_dist_data': rating_dist_data,
    'diff_data': diff_data,
    'abs_diff_data': abs_diff_data,
    'avg_turns_tier': avg_turns_tier,
    'top_openings': top_openings,
    'black_favored': black_favored,
    'ply_data': ply_data,
    'tc_data': tc_data,
    'tc_cat_data': tc_cat_data,
}

js_json = json.dumps(js_data, indent=2)

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Lichess Chess Game Analytics</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
:root {{
  --bg: #0f1117;
  --card: #1a1d2e;
  --border: #2a2d3e;
  --text: #e0e0e0;
  --muted: #8b8fa3;
  --accent: #7c6ff7;
  --accent2: #5ba3f5;
  --white-color: #f0d9b5;
  --black-color: #b58863;
  --draw-color: #6c757d;
  --green: #4caf50;
  --red: #e74c3c;
  --orange: #ff9800;
  --blue: #2196f3;
}}
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}}
.container {{ max-width: 1200px; margin: 0 auto; padding: 2rem 1.5rem; }}
h1 {{
  font-size: 2.2rem;
  font-weight: 700;
  background: linear-gradient(135deg, var(--accent), var(--accent2));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.3rem;
}}
.subtitle {{ color: var(--muted); font-size: 1.05rem; margin-bottom: 2rem; }}
h2 {{
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--accent2);
  margin: 2.5rem 0 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid var(--border);
}}
h3 {{
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--text);
  margin: 1.5rem 0 0.75rem;
}}
p {{ margin-bottom: 0.75rem; color: var(--muted); }}
.kpi-grid {{
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1rem;
  margin: 1.5rem 0;
}}
.kpi-card {{
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
  text-align: center;
}}
.kpi-value {{
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent);
}}
.kpi-label {{
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 0.25rem;
}}
.chart-row {{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
  margin: 1rem 0;
}}
@media (max-width: 800px) {{ .chart-row {{ grid-template-columns: 1fr; }} }}
.chart-card {{
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
}}
.chart-card canvas {{ max-height: 320px; }}
.chart-card.full {{ grid-column: 1 / -1; }}
table {{
  width: 100%;
  border-collapse: collapse;
  margin: 1rem 0;
  font-size: 0.9rem;
}}
th, td {{
  padding: 0.6rem 0.8rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}}
th {{
  background: var(--card);
  color: var(--accent2);
  font-weight: 600;
  position: sticky;
  top: 0;
}}
tr:hover {{ background: rgba(124, 111, 247, 0.05); }}
.tag {{
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
}}
.tag-white {{ background: rgba(240, 217, 181, 0.15); color: var(--white-color); }}
.tag-black {{ background: rgba(181, 136, 99, 0.15); color: var(--black-color); }}
.tag-draw {{ background: rgba(108, 117, 125, 0.15); color: var(--draw-color); }}
.finding-box {{
  background: var(--card);
  border-left: 4px solid var(--accent);
  border-radius: 0 8px 8px 0;
  padding: 1rem 1.25rem;
  margin: 0.75rem 0;
}}
.finding-box strong {{ color: var(--text); }}
.finding-box .detail {{ color: var(--muted); font-size: 0.92rem; margin-top: 0.25rem; }}
</style>
</head>
<body>
<div class="container">

<h1>Lichess Chess Game Analytics</h1>
<p class="subtitle">Patterns of Victory, Openings, and Player Dynamics &mdash; {total_games:,} games analyzed</p>

<!-- ─── KPI BANNER ─────────────────────────────────────────────────────── -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-value">{total_games:,}</div>
    <div class="kpi-label">Total Games</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{white_wr_decisive}%</div>
    <div class="kpi-label">White Win Rate (decisive)</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{avg_turns_overall}</div>
    <div class="kpi-label">Average Turns per Game</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{checkmate_rate}%</div>
    <div class="kpi-label">Checkmate Rate</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{corr_val}</div>
    <div class="kpi-label">Rating Diff ↔ Win Correlation</div>
  </div>
</div>

<!-- ─── SECTION 1 ──────────────────────────────────────────────────────── -->
<h2>1. Dataset Overview &amp; Game Distribution</h2>

<p>The dataset contains <strong>{total_games:,}</strong> games from Lichess.org. Of these,
<strong>{rated_true:,}</strong> ({pct(rated_true, total_games)}%) were rated and
<strong>{rated_false:,}</strong> ({pct(rated_false, total_games)}%) were casual.
Games ended by resignation in <strong>{victory_data.get('resign',0):,}</strong> cases
({pct(victory_data.get('resign',0), total_games)}%),
by checkmate in <strong>{victory_data.get('mate',0):,}</strong> ({pct(victory_data.get('mate',0), total_games)}%),
by timeout in <strong>{victory_data.get('outoftime',0):,}</strong> ({pct(victory_data.get('outoftime',0), total_games)}%),
and by draw in <strong>{victory_data.get('draw',0):,}</strong> ({pct(victory_data.get('draw',0), total_games)}%).
The mean game length is <strong>{avg_turns_overall}</strong> half-moves.</p>

<div class="chart-row">
  <div class="chart-card"><canvas id="chartWinner"></canvas></div>
  <div class="chart-card"><canvas id="chartVictoryStatus"></canvas></div>
</div>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartAvgTurnsByStatus"></canvas></div>
</div>

<!-- ─── SECTION 2 ──────────────────────────────────────────────────────── -->
<h2>2. White vs. Black: The First-Move Advantage</h2>

<p>Across all decisive games, White wins <strong>{white_wr_decisive}%</strong> vs.
Black's <strong>{black_wr_decisive}%</strong>, a margin of
<strong>{round(white_wr_decisive - black_wr_decisive, 1)}</strong> percentage points.
This confirms the well-established first-move advantage in chess.
Draws account for <strong>{pct(draws, total_games)}%</strong> of all games.</p>

<h3>2.1 Color Advantage by Victory Status</h3>
<p>White's edge persists across all victory types, though the magnitude varies. In checkmate endings the advantage is most pronounced, while timeout-based victories show a slightly different pattern — clock management favors the player with more time, often correlated with position quality driven by the first-move initiative.</p>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartColorByVS"></canvas></div>
</div>

<h3>2.2 Color Advantage by Rating Bracket</h3>
<p>Breaking down White's advantage by average player rating reveals how the first-move edge shifts across skill levels. Higher-rated players may convert the initiative more reliably, while lower brackets can show more variance.</p>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartColorByBracket"></canvas></div>
</div>

<h3>2.3 Color Advantage by Time Control</h3>
<p>The 10 most common time controls each show White holding an advantage, though the size of that advantage fluctuates. Faster time controls (bullet) tend to compress decision quality, potentially moderating White's edge.</p>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartColorByTC"></canvas></div>
</div>

<!-- ─── SECTION 3 ──────────────────────────────────────────────────────── -->
<h2>3. Rating Dynamics and Their Impact on Outcomes</h2>

<p>White player ratings average <strong>{rating_stats['white_mean']}</strong> (median {rating_stats['white_median']}, &sigma;={rating_stats['white_std']}),
and Black ratings average <strong>{rating_stats['black_mean']}</strong> (median {rating_stats['black_median']}, &sigma;={rating_stats['black_std']}).
The distributions are nearly symmetric, as expected from the platform's matching algorithm.</p>

<h3>3.1 Rating Distribution</h3>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartRatingDist"></canvas></div>
</div>

<h3>3.2 Rating Differential &amp; Win Probability</h3>
<p>The correlation between rating differential (white &minus; black) and the higher-rated player winning is <strong>{corr_val}</strong>. The chart below shows how win probability climbs steeply as the rating gap widens. A gap of 200+ points gives the stronger player roughly a 70%+ chance of victory; at 400+ the probability exceeds 80%.</p>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartDiffProb"></canvas></div>
</div>

<h3>3.3 Absolute Rating Gap vs. Higher-Rated Win Probability</h3>
<p>Binning by absolute rating difference provides a cleaner view of the monotonic relationship: every 100-point increase in the gap adds roughly 8&ndash;10 percentage points to the higher-rated player's win probability.</p>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartAbsDiffProb"></canvas></div>
</div>

<h3>3.4 Average Game Length by Rating Tier</h3>
<p>Higher-rated players tend to play longer games &mdash; not because the time controls differ, but because stronger players find resources in difficult positions rather than resigning early, and their opening preparation extends the book phase.</p>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartTurnsByTier"></canvas></div>
</div>

<!-- ─── SECTION 4 ──────────────────────────────────────────────────────── -->
<h2>4. Opening Analysis: Popular Openings and Their Success Rates</h2>

<h3>4.1 Top 15 Openings by Frequency</h3>
<p>The table below shows the 15 most-played openings. Win rates are calculated on decisive games only (draws excluded). The Sicilian Defense and King's Pawn Game dominate in frequency.</p>

<table>
<thead>
<tr><th>#</th><th>ECO</th><th>Opening</th><th>Games</th><th>W Win %</th><th>B Win %</th><th>Draw %</th><th>Avg Ply</th><th>Avg Turns</th></tr>
</thead>
<tbody>
"""

for i, op in enumerate(top_openings, 1):
    w_tag = 'tag-white' if op['white_pct'] > op['black_pct'] else ''
    b_tag = 'tag-black' if op['black_pct'] > op['white_pct'] else ''
    html += f"""<tr>
  <td>{i}</td>
  <td>{op['eco']}</td>
  <td>{op['name'][:50]}</td>
  <td>{op['total']}</td>
  <td><span class="tag {w_tag}">{op['white_pct']}%</span></td>
  <td><span class="tag {b_tag}">{op['black_pct']}%</span></td>
  <td><span class="tag tag-draw">{op['draw_pct']}%</span></td>
  <td>{op['avg_ply']}</td>
  <td>{op['avg_turns']}</td>
</tr>"""

html += f"""
</tbody>
</table>

<div class="chart-row">
  <div class="chart-card full"><canvas id="chartTopOpenings"></canvas></div>
</div>

<h3>4.2 Openings Where Black Outperforms White</h3>
<p>Most openings favor White, but a few notable exceptions exist. The following openings (minimum 50 games, 30 decisive) show Black achieving a higher win rate than White &mdash; suggesting these lines may offer Black practical counterplay or that White's theoretical advantage is harder to convert.</p>

<table>
<thead><tr><th>ECO</th><th>Opening</th><th>Games</th><th>W Win %</th><th>B Win %</th><th>Edge</th></tr></thead>
<tbody>
"""
for op in black_favored:
    edge = round(op['black_pct'] - op['white_pct'], 1)
    html += f"""<tr>
  <td>{op['eco']}</td>
  <td>{op['name'][:50]}</td>
  <td>{op['total']}</td>
  <td>{op['white_pct']}%</td>
  <td>{op['black_pct']}%</td>
  <td><span class="tag tag-black">+{edge}% B</span></td>
</tr>"""

html += f"""
</tbody>
</table>

<h3>4.3 Opening Depth (Ply) vs. Outcome</h3>
<p>Longer opening book sequences correlate with more draws and slightly more balanced outcomes, as both players enter well-explored territory where theoretical preparation levels the playing field.</p>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartPlyOutcome"></canvas></div>
</div>

<!-- ─── SECTION 5 ──────────────────────────────────────────────────────── -->
<h2>5. Time Control Patterns and Game Characteristics</h2>

<h3>5.1 Time Control Categories</h3>
<p>Games are classified into Bullet (&le;3 min), Blitz (4&ndash;10 min), Rapid (11&ndash;30 min), and Classical (&gt;30 min) based on base time. The distribution of victory types shifts meaningfully: faster games see more timeouts; longer games see more checkmates and draws.</p>

<table>
<thead><tr><th>Category</th><th>Games</th><th>Avg Turns</th><th>W Win %</th><th>B Win %</th><th>Mate %</th><th>Resign %</th><th>Timeout %</th><th>Draw %</th></tr></thead>
<tbody>
"""
for cat in tc_cat_data:
    html += f"""<tr>
  <td>{cat['category']}</td>
  <td>{cat['total']}</td>
  <td>{cat['avg_turns']}</td>
  <td>{cat['white_pct']}%</td>
  <td>{cat['black_pct']}%</td>
  <td>{cat['mate_pct']}%</td>
  <td>{cat['resign_pct']}%</td>
  <td>{cat['outoftime_pct']}%</td>
  <td>{cat['draw_pct']}%</td>
</tr>"""

html += f"""
</tbody>
</table>

<div class="chart-row">
  <div class="chart-card"><canvas id="chartTCCatVictory"></canvas></div>
  <div class="chart-card"><canvas id="chartTCCatColor"></canvas></div>
</div>

<h3>5.2 Top 12 Specific Time Controls</h3>
<div class="chart-row">
  <div class="chart-card full"><canvas id="chartTCDetail"></canvas></div>
</div>

<!-- ─── SECTION 6 ──────────────────────────────────────────────────────── -->
<h2>6. Key Findings and Strategic Takeaways</h2>

<div class="finding-box">
  <strong>White's first-move advantage is consistent but modest.</strong>
  <div class="detail">White wins {white_wr_decisive}% of decisive games &mdash; a {round(white_wr_decisive - black_wr_decisive, 1)}pp edge over Black. The advantage holds across all rating brackets and time controls, though it narrows slightly in bullet (where clock pressure dominates) and widens among higher-rated players who convert initiative more reliably.</div>
</div>

<div class="finding-box">
  <strong>Rating differential is the single strongest predictor of outcomes.</strong>
  <div class="detail">A {corr_val} correlation between rating gap and higher-rated player winning. A 200-point gap yields ~70% win probability for the stronger player; 400+ points pushes it above 80%. This relationship is near-monotonic across all bin sizes, confirming Elo's predictive validity on Lichess.</div>
</div>

<div class="finding-box">
  <strong>Resignation dominates game endings; checkmate is relatively rare.</strong>
  <div class="detail">{pct(victory_data.get('resign',0), total_games)}% of games end by resignation vs. only {checkmate_rate}% by checkmate. This reflects modern chess culture: players resign lost positions rather than playing to mate. However, in bullet, timeouts ({pct(victory_data.get('outoftime',0), total_games)}% overall) rise significantly as clock management becomes critical.</div>
</div>

<div class="finding-box">
  <strong>Time control reshapes how games end more than who wins.</strong>
  <div class="detail">White's win rate stays within a narrow band across bullet/blitz/rapid/classical, but the <em>victory type</em> distribution shifts dramatically. Bullet sees far more timeouts; classical sees more checkmates and draws. Coaches should note that bullet outcomes are less positionally determined.</div>
</div>

<div class="finding-box">
  <strong>A handful of openings give Black a practical edge.</strong>
  <div class="detail">While White outperforms in most top-15 openings, {len(black_favored)} openings with 50+ games show Black winning more often. These are potential repertoire choices for Black players seeking a statistical edge in specific lines, though sample-size caveats apply.</div>
</div>

<div class="finding-box">
  <strong>Higher-rated players play longer games.</strong>
  <div class="detail">Average turns increase with rating tier, suggesting stronger players both navigate opening theory more deeply and resist resigning in slightly worse positions &mdash; finding resources that lower-rated players miss.</div>
</div>

</div><!-- /container -->

<script>
const DATA = {js_json};

// ── Palette ──
const C = {{
  white: '#f0d9b5',
  black: '#b58863',
  draw: '#6c757d',
  accent: '#7c6ff7',
  accent2: '#5ba3f5',
  green: '#4caf50',
  red: '#e74c3c',
  orange: '#ff9800',
  blue: '#2196f3',
  purple: '#9c27b0',
  teal: '#009688',
}};

Chart.defaults.color = '#8b8fa3';
Chart.defaults.borderColor = '#2a2d3e';
Chart.defaults.font.family = "'Segoe UI', system-ui, sans-serif";

// ── Section 1 charts ──
new Chart(document.getElementById('chartWinner'), {{
  type: 'doughnut',
  data: {{
    labels: ['White', 'Black', 'Draw'],
    datasets: [{{
      data: [DATA.winner_data.white, DATA.winner_data.black, DATA.winner_data.draw],
      backgroundColor: [C.white, C.black, C.draw],
      borderWidth: 0,
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{
      title: {{ display: true, text: 'Game Outcomes by Winner', font: {{ size: 14 }} }},
      legend: {{ position: 'bottom' }},
    }},
  }}
}});

new Chart(document.getElementById('chartVictoryStatus'), {{
  type: 'doughnut',
  data: {{
    labels: Object.keys(DATA.victory_data).map(k => k.charAt(0).toUpperCase() + k.slice(1)),
    datasets: [{{
      data: Object.values(DATA.victory_data),
      backgroundColor: [C.green, C.red, C.orange, C.draw],
      borderWidth: 0,
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{
      title: {{ display: true, text: 'Victory Status Distribution', font: {{ size: 14 }} }},
      legend: {{ position: 'bottom' }},
    }},
  }}
}});

new Chart(document.getElementById('chartAvgTurnsByStatus'), {{
  type: 'bar',
  data: {{
    labels: Object.keys(DATA.victory_data).map(k => k.charAt(0).toUpperCase() + k.slice(1)),
    datasets: [{{
      label: 'Avg Turns',
      data: Object.keys(DATA.victory_data).map(k => ({{
        'mate': {avg_turns_by_status.get('mate', 0)},
        'resign': {avg_turns_by_status.get('resign', 0)},
        'outoftime': {avg_turns_by_status.get('outoftime', 0)},
        'draw': {avg_turns_by_status.get('draw', 0)},
      }})[k]),
      backgroundColor: [C.green, C.red, C.orange, C.draw],
      borderRadius: 6,
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Average Game Length by Victory Status', font: {{ size: 14 }} }} }},
    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Turns' }} }} }},
  }}
}});

// ── Section 2 charts ──
new Chart(document.getElementById('chartColorByVS'), {{
  type: 'bar',
  data: {{
    labels: DATA.color_by_vs.map(d => d.status.charAt(0).toUpperCase() + d.status.slice(1)),
    datasets: [
      {{ label: 'White Win %', data: DATA.color_by_vs.map(d => d.white_pct), backgroundColor: C.white, borderRadius: 4 }},
      {{ label: 'Black Win %', data: DATA.color_by_vs.map(d => d.black_pct), backgroundColor: C.black, borderRadius: 4 }},
    ]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Win Rate by Color & Victory Status', font: {{ size: 14 }} }} }},
    scales: {{ y: {{ beginAtZero: true, max: 65 }} }},
  }}
}});

new Chart(document.getElementById('chartColorByBracket'), {{
  type: 'bar',
  data: {{
    labels: DATA.color_by_bracket.map(d => d.bracket),
    datasets: [
      {{ label: 'White Win %', data: DATA.color_by_bracket.map(d => d.white_pct), backgroundColor: C.white, borderRadius: 4 }},
      {{ label: 'Black Win %', data: DATA.color_by_bracket.map(d => d.black_pct), backgroundColor: C.black, borderRadius: 4 }},
    ]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Win Rate by Color & Rating Bracket', font: {{ size: 14 }} }} }},
    scales: {{ y: {{ beginAtZero: true, max: 65 }} }},
  }}
}});

new Chart(document.getElementById('chartColorByTC'), {{
  type: 'bar',
  data: {{
    labels: DATA.color_by_tc.map(d => d.tc),
    datasets: [
      {{ label: 'White Win %', data: DATA.color_by_tc.map(d => d.white_pct), backgroundColor: C.white, borderRadius: 4 }},
      {{ label: 'Black Win %', data: DATA.color_by_tc.map(d => d.black_pct), backgroundColor: C.black, borderRadius: 4 }},
    ]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Win Rate by Color & Time Control (Top 10)', font: {{ size: 14 }} }} }},
    scales: {{ y: {{ beginAtZero: true, max: 65 }} }},
  }}
}});

// ── Section 3 charts ──
new Chart(document.getElementById('chartRatingDist'), {{
  type: 'line',
  data: {{
    labels: DATA.rating_dist_data.map(d => d.rating),
    datasets: [
      {{ label: 'White Players', data: DATA.rating_dist_data.map(d => d.white), borderColor: C.white, backgroundColor: 'rgba(240,217,181,0.1)', fill: true, tension: 0.3, pointRadius: 0 }},
      {{ label: 'Black Players', data: DATA.rating_dist_data.map(d => d.black), borderColor: C.black, backgroundColor: 'rgba(181,136,99,0.1)', fill: true, tension: 0.3, pointRadius: 0 }},
    ]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Player Rating Distribution', font: {{ size: 14 }} }} }},
    scales: {{
      x: {{ title: {{ display: true, text: 'Rating' }} }},
      y: {{ title: {{ display: true, text: 'Count' }} }},
    }},
  }}
}});

new Chart(document.getElementById('chartDiffProb'), {{
  type: 'scatter',
  data: {{
    datasets: [{{
      label: 'Higher-Rated Win Prob %',
      data: DATA.diff_data.map(d => ({{ x: d.diff, y: d.win_prob }})),
      backgroundColor: C.accent,
      pointRadius: 3,
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Rating Differential (W-B) vs Higher-Rated Win Probability', font: {{ size: 14 }} }} }},
    scales: {{
      x: {{ title: {{ display: true, text: 'Rating Differential (White - Black)' }} }},
      y: {{ title: {{ display: true, text: 'Win Probability %' }}, min: 0, max: 100 }},
    }},
  }}
}});

new Chart(document.getElementById('chartAbsDiffProb'), {{
  type: 'bar',
  data: {{
    labels: DATA.abs_diff_data.map(d => d.label),
    datasets: [{{
      label: 'Higher-Rated Win %',
      data: DATA.abs_diff_data.map(d => d.win_prob),
      backgroundColor: C.accent2,
      borderRadius: 4,
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Absolute Rating Gap vs Higher-Rated Win Probability', font: {{ size: 14 }} }} }},
    scales: {{
      x: {{ title: {{ display: true, text: 'Rating Gap' }} }},
      y: {{ title: {{ display: true, text: 'Win Probability %' }}, min: 40, max: 100 }},
    }},
  }}
}});

new Chart(document.getElementById('chartTurnsByTier'), {{
  type: 'bar',
  data: {{
    labels: DATA.avg_turns_tier.map(d => d.tier),
    datasets: [{{
      label: 'Avg Turns',
      data: DATA.avg_turns_tier.map(d => d.avg_turns),
      backgroundColor: C.teal,
      borderRadius: 4,
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Average Game Length by Rating Tier', font: {{ size: 14 }} }} }},
    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Turns' }} }} }},
  }}
}});

// ── Section 4 charts ──
const opLabels = DATA.top_openings.map((d, i) => d.eco + ' ' + d.name.substring(0, 30));
new Chart(document.getElementById('chartTopOpenings'), {{
  type: 'bar',
  data: {{
    labels: opLabels,
    datasets: [
      {{ label: 'White Win %', data: DATA.top_openings.map(d => d.white_pct), backgroundColor: C.white, borderRadius: 4 }},
      {{ label: 'Black Win %', data: DATA.top_openings.map(d => d.black_pct), backgroundColor: C.black, borderRadius: 4 }},
      {{ label: 'Draw %', data: DATA.top_openings.map(d => d.draw_pct), backgroundColor: C.draw, borderRadius: 4 }},
    ]
  }},
  options: {{
    responsive: true,
    indexAxis: 'y',
    plugins: {{ title: {{ display: true, text: 'Top 15 Openings: Win Rates', font: {{ size: 14 }} }} }},
    scales: {{ x: {{ max: 80 }} }},
  }}
}});

new Chart(document.getElementById('chartPlyOutcome'), {{
  type: 'bar',
  data: {{
    labels: DATA.ply_data.map(d => d.label),
    datasets: [
      {{ label: 'White Win %', data: DATA.ply_data.map(d => d.white_pct), backgroundColor: C.white, borderRadius: 4 }},
      {{ label: 'Black Win %', data: DATA.ply_data.map(d => d.black_pct), backgroundColor: C.black, borderRadius: 4 }},
      {{ label: 'Draw %', data: DATA.ply_data.map(d => d.draw_pct), backgroundColor: C.draw, borderRadius: 4 }},
    ]
  }},
  options: {{
    responsive: true,
    plugins: {{ title: {{ display: true, text: 'Opening Depth (Ply) vs Outcome', font: {{ size: 14 }} }} }},
    scales: {{ y: {{ beginAtZero: true, max: 80 }} }},
  }}
}});

// ── Section 5 charts ──
new Chart(document.getElementById('chartTCCatVictory'), {{
  type: 'bar',
  data: {{
    labels: DATA.tc_cat_data.map(d => d.category),
    datasets: [
