# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
total_games = len(df)

# ── Helper: safe percent ───────────────────────────────────────────────────
def pct(n, total):
    return round(100 * n / total, 2) if total else 0

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 1 — Dataset Overview & Game Distribution
# ═══════════════════════════════════════════════════════════════════════════
rated_counts = df['rated'].value_counts()
rated_true = int(rated_counts.get(True, 0))
rated_false = int(rated_counts.get(False, 0))

victory_counts = df['victory_status'].value_counts()
victory_data = {k: int(v) for k, v in victory_counts.items()}

winner_counts = df['winner'].value_counts()
winner_data = {k: int(v) for k, v in winner_counts.items()}

decisive_games = df[df['winner'] != 'draw']
decisive_total = len(decisive_games)

# Average turns overall and by victory status
avg_turns_overall = round(df['turns'].mean(), 1)
avg_turns_by_status = df.groupby('victory_status')['turns'].mean().round(1).to_dict()

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 2 — White vs. Black: First-Move Advantage
# ═══════════════════════════════════════════════════════════════════════════
white_wins = int(winner_data.get('white', 0))
black_wins = int(winner_data.get('black', 0))
draws = int(winner_data.get('draw', 0))

white_wr_decisive = pct(white_wins, decisive_total)
black_wr_decisive = pct(black_wins, decisive_total)

# By rating bracket
def rating_bracket(r):
    if r < 1000: return '<1000'
    elif r < 1200: return '1000-1199'
    elif r < 1400: return '1200-1399'
    elif r < 1600: return '1400-1599'
    elif r < 1800: return '1600-1799'
    elif r < 2000: return '1800-1999'
    else: return '2000+'

df['avg_rating'] = (df['white_rating'] + df['black_rating']) / 2
df['rating_bracket'] = df['avg_rating'].apply(rating_bracket)

bracket_order = ['<1000', '1000-1199', '1200-1399', '1400-1599', '1600-1799', '1800-1999', '2000+']

color_by_bracket = []
for b in bracket_order:
    sub = df[df['rating_bracket'] == b]
    dec = sub[sub['winner'] != 'draw']
    n = len(dec)
    if n == 0:
        continue
    w = len(dec[dec['winner'] == 'white'])
    bl = len(dec[dec['winner'] == 'black'])
    color_by_bracket.append({
        'bracket': b,
        'total': n,
        'white_pct': pct(w, n),
        'black_pct': pct(bl, n),
    })

# By time control (top N)
top_increments = df['increment_code'].value_counts().head(10).index.tolist()
color_by_tc = []
for tc in top_increments:
    sub = df[df['increment_code'] == tc]
    dec = sub[sub['winner'] != 'draw']
    n = len(dec)
    if n == 0:
        continue
    w = len(dec[dec['winner'] == 'white'])
    bl = len(dec[dec['winner'] == 'black'])
    color_by_tc.append({
        'tc': tc,
        'total': n,
        'white_pct': pct(w, n),
        'black_pct': pct(bl, n),
    })

# By victory status
color_by_vs = []
for vs in ['mate', 'resign', 'outoftime']:
    sub = df[df['victory_status'] == vs]
    n = len(sub)
    if n == 0:
        continue
    w = len(sub[sub['winner'] == 'white'])
    bl = len(sub[sub['winner'] == 'black'])
    color_by_vs.append({
        'status': vs,
        'total': n,
        'white_pct': pct(w, n),
        'black_pct': pct(bl, n),
    })

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 3 — Rating Dynamics
# ═══════════════════════════════════════════════════════════════════════════
rating_stats = {
    'white_mean': round(df['white_rating'].mean(), 1),
    'white_median': round(df['white_rating'].median(), 1),
    'white_std': round(df['white_rating'].std(), 1),
    'black_mean': round(df['black_rating'].mean(), 1),
    'black_median': round(df['black_rating'].median(), 1),
    'black_std': round(df['black_rating'].std(), 1),
}

# Rating distribution histogram bins
rating_bins = list(range(600, 2801, 100))
white_hist = pd.cut(df['white_rating'], bins=rating_bins).value_counts().sort_index()
black_hist = pd.cut(df['black_rating'], bins=rating_bins).value_counts().sort_index()

rating_dist_data = []
for interval in white_hist.index:
    mid = int((interval.left + interval.right) / 2)
    rating_dist_data.append({
        'rating': mid,
        'white': int(white_hist.get(interval, 0)),
        'black': int(black_hist.get(interval, 0)),
    })

# Rating differential vs win probability
df['rating_diff'] = df['white_rating'] - df['black_rating']
df_decisive = df[df['winner'] != 'draw'].copy()
df_decisive['higher_rated_won'] = (
    ((df_decisive['rating_diff'] > 0) & (df_decisive['winner'] == 'white')) |
    ((df_decisive['rating_diff'] < 0) & (df_decisive['winner'] == 'black'))
)

# Bin rating differentials
diff_bins = list(range(-800, 801, 50))
df_decisive['diff_bin'] = pd.cut(df_decisive['rating_diff'], bins=diff_bins)

diff_analysis = df_decisive.groupby('diff_bin', observed=True).agg(
    total=('winner', 'count'),
    higher_won=('higher_rated_won', 'sum')
).reset_index()
diff_analysis['win_prob'] = (diff_analysis['higher_won'] / diff_analysis['total'] * 100).round(1)
diff_analysis['mid'] = diff_analysis['diff_bin'].apply(lambda x: int((x.left + x.right) / 2))

diff_data = []
for _, row in diff_analysis.iterrows():
    if row['total'] >= 10:
        diff_data.append({
            'diff': row['mid'],
            'win_prob': float(row['win_prob']),
            'count': int(row['total']),
        })

# Absolute rating diff vs higher-rated win prob
df_decisive['abs_diff'] = df_decisive['rating_diff'].abs()
abs_bins = [0, 25, 50, 75, 100, 150, 200, 300, 400, 500, 600, 800, 1000, 1500, 2000]
df_decisive['abs_diff_bin'] = pd.cut(df_decisive['abs_diff'], bins=abs_bins)

abs_diff_analysis = df_decisive.groupby('abs_diff_bin', observed=True).agg(
    total=('winner', 'count'),
    higher_won=('higher_rated_won', 'sum')
).reset_index()
abs_diff_analysis['win_prob'] = (abs_diff_analysis['higher_won'] / abs_diff_analysis['total'] * 100).round(1)
abs_diff_analysis['label'] = abs_diff_analysis['abs_diff_bin'].apply(lambda x: f"{int(x.left)}-{int(x.right)}")

abs_diff_data = []
for _, row in abs_diff_analysis.iterrows():
    if row['total'] >= 10:
        abs_diff_data.append({
            'label': row['label'],
            'win_prob': float(row['win_prob']),
            'count': int(row['total']),
        })

# Correlation
corr_val = round(df_decisive['rating_diff'].corr(df_decisive['higher_rated_won'].astype(int)), 3)

# Avg turns by rating tier
tier_order = ['<1000', '1000-1199', '1200-1399', '1400-1599', '1600-1799', '1800-1999', '2000+']
df['white_tier'] = df['white_rating'].apply(rating_bracket)
df['black_tier'] = df['black_rating'].apply(rating_bracket)

avg_turns_tier = []
for t in tier_order:
    sub = df[(df['white_tier'] == t) | (df['black_tier'] == t)]
    if len(sub) > 0:
        avg_turns_tier.append({
            'tier': t,
            'avg_turns': round(sub['turns'].mean(), 1),
            'games': len(sub),
        })

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 4 — Opening Analysis
# ═══════════════════════════════════════════════════════════════════════════
# Top openings by ECO + name
opening_counts = df.groupby(['opening_eco', 'opening_name']).size().reset_index(name='count')
opening_counts = opening_counts.sort_values('count', ascending=False).head(15)

top_openings = []
for _, row in opening_counts.iterrows():
    eco = row['opening_eco']
    name = row['opening_name']
    sub = df[(df['opening_eco'] == eco) & (df['opening_name'] == name)]
    dec = sub[sub['winner'] != 'draw']
    n_dec = len(dec)
    w = len(dec[dec['winner'] == 'white']) if n_dec else 0
    bl = len(dec[dec['winner'] == 'black']) if n_dec else 0
    dr = len(sub[sub['winner'] == 'draw'])
    top_openings.append({
        'eco': eco,
        'name': name,
        'total': int(row['count']),
        'white_pct': pct(w, n_dec) if n_dec else 0,
        'black_pct': pct(bl, n_dec) if n_dec else 0,
        'draw_pct': pct(dr, len(sub)),
        'avg_ply': round(sub['opening_ply'].mean(), 1),
        'avg_turns': round(sub['turns'].mean(), 1),
    })

# Openings where black outperforms white (top 30 by frequency)
all_openings = df.groupby(['opening_eco', 'opening_name']).agg(
    total=('id', 'count'),
    white_wins=('winner', lambda x: (x == 'white').sum()),
    black_wins=('winner', lambda x: (x == 'black').sum()),
    draws=('winner', lambda x: (x == 'draw').sum()),
).reset_index()
all_openings = all_openings[all_openings['total'] >= 50].sort_values('total', ascending=False)

black_favored = []
for _, row in all_openings.head(50).iterrows():
    dec = row['total'] - row['draws']
    if dec >= 30:
        bp = pct(row['black_wins'], dec)
        wp = pct(row['white_wins'], dec)
        if bp > wp:
            black_favored.append({
                'eco': row['opening_eco'],
                'name': row['opening_name'],
                'total': int(row['total']),
                'white_pct': wp,
                'black_pct': bp,
            })

black_favored = sorted(black_favored, key=lambda x: x['black_pct'] - x['white_pct'], reverse=True)[:5]

# Opening ply vs outcome
ply_bins = [0, 2, 4, 6, 8, 10, 15, 20, 30, 50]
df['ply_bin'] = pd.cut(df['opening_ply'], bins=ply_bins)
ply_analysis = df.groupby('ply_bin', observed=True).agg(
    total=('id', 'count'),
    white_wins=('winner', lambda x: (x == 'white').sum()),
    black_wins=('winner', lambda x: (x == 'black').sum()),
    draws=('winner', lambda x: (x == 'draw').sum()),
    avg_turns=('turns', 'mean'),
).reset_index()
ply_analysis['label'] = ply_analysis['ply_bin'].apply(lambda x: f"{int(x.left)}-{int(x.right)}")

ply_data = []
for _, row in ply_analysis.iterrows():
    dec = row['total'] - row['draws']
    ply_data.append({
        'label': row['label'],
        'total': int(row['total']),
        'white_pct': pct(row['white_wins'], dec) if dec else 0,
        'black_pct': pct(row['black_wins'], dec) if dec else 0,
        'draw_pct': pct(row['draws'], row['total']),
        'avg_turns': round(row['avg_turns'], 1),
    })

# ═══════════════════════════════════════════════════════════════════════════
#  SECTION 5 — Time Control Patterns
# ═══════════════════════════════════════════════════════════════════════════
tc_counts = df['increment_code'].value_counts().head(12)
tc_data = []
for tc, count in tc_counts.items():
    sub = df[df['increment_code'] == tc]
    vs_dist = sub['victory_status'].value_counts(normalize=True).mul(100).round(1).to_dict()
    tc_data.append({
        'tc': tc,
        'total': int(count),
        'avg_turns': round(sub['turns'].mean(), 1),
        'mate_pct': float(vs_dist.get('mate', 0)),
        'resign_pct': float(vs_dist.get('resign', 0)),
        'outoftime_pct': float(vs_dist.get('outoftime', 0)),
        'draw_pct': float(vs_dist.get('draw', 0)),
    })

# Classify time controls
def classify_tc(tc):
    try:
        base = int(tc.split('+')[0])
        if base <= 3: return 'Bullet'
        elif base <= 10: return 'Blitz'
        elif base <= 30: return 'Rapid'
        else: return 'Classical'
    except:
        return 'Other'

df['tc_category'] = df['increment_code'].apply(classify_tc)

tc_cat_order = ['Bullet', 'Blitz', 'Rapid', 'Classical']
tc_cat_data = []
for cat in tc_cat_order:
    sub = df[df['tc_category'] == cat]
    if len(sub) == 0:
        continue
    dec = sub[sub['winner'] != 'draw']
    n_dec = len(dec)
    vs_dist = sub['victory_status'].value_counts(normalize=True).mul(100).round(1).to_dict()
    tc_cat_data.append({
        'category': cat,
        'total': len(sub),
        'avg_turns': round(sub['turns'].mean(), 1),
        'white_pct': pct(len(dec[dec['winner'] == 'white']), n_dec) if n_dec else 0,
        'black_pct': pct(len(dec[dec['winner'] == 'black']), n_dec) if n_dec else 0,
        'mate_pct': float(vs_dist.get('mate', 0)),
        'resign_pct': float(vs_dist.get('resign', 0)),
        'outoftime_pct': float(vs_dist.get('outoftime', 0)),
        'draw_pct': float(vs_dist.get('draw', 0)),
    })

# ═══════════════════════════════════════════════════════════════════════════
#  KPI Calculations
# ═══════════════════════════════════════════════════════════════════════════
checkmate_rate = pct(victory_data.get('mate', 0), total_games)
resign_rate = pct(victory_data.get('resign', 0), total_games)
outoftime_rate = pct(victory_data.get('outoftime', 0), total_games)

# ═══════════════════════════════════════════════════════════════════════════
#  BUILD HTML
# ═══════════════════════════════════════════════════════════════════════════

# Serialize data for JS charts
js_data = {
    'winner_data': winner_data,
    'victory_data': victory_data,
    'color_by_bracket': color_by_bracket,
    'color_by_tc': color_by_tc,
    'color_by_vs': color_by_vs,
    'rating_dist_data': rating_dist_data,
    'diff_data': diff_data,
    'abs_diff_data': abs_diff_data,
    'avg_turns_tier': avg_turns_tier,
    'top_openings': top_openings,
    'black_favored': black_favored,
    'ply_data': ply_data,
    'tc_data': tc_data,
    'tc_cat_data': tc_cat_data,
}

js_json = json.dumps(js_data, indent=2)

html = f"""<!DOCTYPE html>
